import base64
import json
import socket
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from typing import Any


@dataclass
class Response:
    status: int
    headers: dict[str, str]
    body: bytes

    def json(self) -> Any:
        return json.loads(self.body.decode("utf-8")) if self.body else None

    @property
    def text(self) -> str:
        return self.body.decode("utf-8", errors="replace")


class HttpClient:
    def __init__(self, base_url: str, timeout: float = 10):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def request(
        self,
        method: str,
        path: str,
        *,
        token: str | None = None,
        headers: dict[str, str] | None = None,
        json_body: Any | None = None,
        form: dict[str, str] | None = None,
    ) -> Response:
        supplied = {key: value for key, value in (headers or {}).items()}
        if token:
            supplied["Authorization"] = f"Bearer {token}"
        body: bytes | None = None
        if json_body is not None:
            body = json.dumps(json_body, separators=(",", ":")).encode("utf-8")
            supplied.setdefault("Content-Type", "application/json")
        elif form is not None:
            body = urllib.parse.urlencode(form).encode("ascii")
            supplied.setdefault("Content-Type", "application/x-www-form-urlencoded")
        url = path if path.startswith(("http://", "https://")) else self.base_url + "/" + path.lstrip("/")
        request = urllib.request.Request(url, data=body, headers=supplied, method=method.upper())
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return Response(
                    status=response.status,
                    headers={key.lower(): value for key, value in response.headers.items()},
                    body=response.read(),
                )
        except urllib.error.HTTPError as error:
            return Response(
                status=error.code,
                headers={key.lower(): value for key, value in error.headers.items()},
                body=error.read(),
            )


class MediaPulseApi:
    def __init__(self, base_url: str, token_url: str, auth: dict[str, Any]):
        self.http = HttpClient(base_url)
        self.token_http = HttpClient(token_url.rsplit("/", 1)[0])
        self.token_url = token_url
        self.auth = auth

    @classmethod
    def from_manifest(cls, manifest: dict[str, Any], default_endpoint: str) -> "MediaPulseApi":
        lb = manifest.get("load_balancer") if isinstance(manifest.get("load_balancer"), dict) else {}
        base_url = str(
            lb.get("connect_url")
            or manifest.get("connect_url")
            or lb.get("base_url")
            or default_endpoint
        ).rstrip("/")
        auth = manifest.get("auth") if isinstance(manifest.get("auth"), dict) else {}
        token_url = str(auth.get("token_endpoint") or f"{default_endpoint.rstrip('/')}/oauth2/v4/token")
        return cls(base_url=base_url, token_url=token_url, auth=auth)

    def token(self, scope: str) -> str:
        role = "read"
        if "admin" in scope:
            role = "admin"
        elif "write" in scope:
            role = "write"
        client_id = str(
            self.auth.get(f"{role}_client_id")
            or self.auth.get(f"{role}_client_email")
            or f"mediapulse-{role}-client"
        )
        client_secret = str(
            self.auth.get(f"{role}_client_secret")
            or self.auth.get(f"{role}_private_key")
            or "mediapulse-secret"
        )
        response = self.token_http.request(
            "POST",
            self.token_url,
            form={
                "grant_type": "client_credentials",
                "client_id": client_id,
                "client_secret": client_secret,
                "scope": scope,
            },
        )
        if response.status != 200:
            raise ValueError(f"OAuth2 token request for {scope} returned {response.status}: {response.text[:200]}")
        payload = response.json()
        token = payload.get("access_token") if isinstance(payload, dict) else None
        if not token:
            raise ValueError(f"OAuth2 token response for {scope} has no access_token")
        return str(token)

    def health(self, ready: bool = True) -> Response:
        return self.http.request("GET", "/health/ready" if ready else "/health/live")

    def create_media(
        self,
        *,
        token: str | None,
        media_id: str,
        owner_id: str,
        reference: str,
        origin: str,
        destination: str,
        idempotency_key: str,
        correlation_id: str,
    ) -> Response:
        return self.http.request(
            "POST",
            "/v1/media",
            token=token,
            headers={"Idempotency-Key": idempotency_key, "X-Correlation-ID": correlation_id},
            json_body={
                "mediaId": media_id,
                "ownerId": owner_id,
                "reference": reference,
                "origin": origin,
                "destination": destination,
                "expectedVersion": 0,
            },
        )

    def add_stage(
        self,
        *,
        token: str | None,
        media_id: str,
        stage_id: str,
        location: str,
        status: str,
        occurred_at: str,
        expected_version: int,
        idempotency_key: str,
        correlation_id: str,
    ) -> Response:
        return self.http.request(
            "POST",
            f"/v1/media/{urllib.parse.quote(media_id, safe='')}/stages",
            token=token,
            headers={"Idempotency-Key": idempotency_key, "X-Correlation-ID": correlation_id},
            json_body={
                "stageId": stage_id,
                "location": location,
                "status": status,
                "occurredAt": occurred_at,
                "expectedVersion": expected_version,
            },
