  })
}

resource "google_pubsub_topic" "events" {
  name                       = "${var.prefix}-events"
  kms_key_name               = google_kms_crypto_key.messaging.id
  message_retention_duration = "345600s"

  labels = merge(local.common_labels, {
    role = "domain-events"
  })
}

resource "google_pubsub_subscription" "processor_push" {
  name                       = "${var.prefix}-events-processor-sub"
  topic                      = google_pubsub_topic.events.name
  ack_deadline_seconds       = 20
  message_retention_duration = "345600s"
  enable_message_ordering    = true

  push_config {
    push_endpoint = google_cloudfunc",
  "output_tail": "ry_count          = 2
    min_backoff_duration = "2s"
    max_backoff_duration = "15s"
  }

  http_target {
    http_method = "POST"
    uri         = google_cloudfunctions2_function.relay.url
    body        = base64encode(jsonencode({ source = "cloud.scheduler", action = "flush_outbox" }))

    headers = {
      "Content-Type" = "application/json"
    }

    oidc_token {
      service_account_email = google_service_account.scheduler.email
      audience              = google_cloudfunctions2_function.relay.url
    }
  }
}

resource "google_cloud_scheduler_job" "archiver" {
  name             = "${var.prefix}-archiver-schedule"
  region           = var.gcp_region
  description      = "Triggers Audit Archiver function every 5 minutes to export published events to GCS"
  schedule         = "*/5 * * * *"
  time_zone        = "Etc/UTC"
  attempt_deadline = "60s"

  retry_config {
    retry_count          = 2
    min_backoff_duration = "5s"
    max_backoff_duration = "30s"
  }

  http_target {
    http_method = "POST"
    uri         = google_cloudfunctions2_function.archiver.url
    body        = base64encode(jsonencode({ source = "cloud.scheduler", action = "archive_events" }))

    headers = {
      "Content-Type" = "application/json"
    }

    oidc_token {
      service_account_email = google_service_account.scheduler.email
      audience              = google_cloudfunctions2_function.archiver.url
    }
  }
}
resource "google_sql_database_instance" "events" {
  name                = "${var.prefix}-events-pg"
  region              = var.gcp_region
  database_version    = "POSTGRES_16"
  encryption_key_name = google_kms_crypto_key.database.id
  deletion_protection = false

  settings {
    tier              = "db-custom-2-4096"
    availability_type = "ZONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.ingest.id
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    user_labels = merge(local.common_labels, {
      data_role  = "event-store-outbox"
      encryption = "cmek"
    })
  }
}

